package in.kabadiwala.connect.integration; import in.kabadiwala.connect.model.Payment; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import java.util.Map; @Component @ConditionalOnProperty(name="app.payment.provider",havingValue="manual",matchIfMissing=true) public class ManualPaymentProvider implements PaymentProvider {public String name(){return "MANUAL";} public Map<String,Object> initiate(Payment p){return Map.of("mode","MANUAL","message","Record payment only after offline/UPI/bank settlement is independently confirmed");} public boolean verify(String a,String b,String c){return false;}}
